local config = {
  ui_story_30120401_1_dialog_content = "Kamu butuh sesuatu, Nemesis?",
  ui_story_30120401_2_dialog_content = "Ini bukan tempat yang tepat untuk bicara. Ikut denganku ke Gannon City.",
  ui_story_30120401_3_dialog_content = "Eh... Baiklah.",
  ui_story_30120401_4_dialog_content = "(Nemesis bertingkah sedikit misterius hari ini... Aku ingin tahu apa ada yang salah.)",
  ui_story_30120401_5_dialog_content = "(Kudengar dia adalah General Inspector, dan dia ingin aku pergi bersamanya ke Gannon City... Jangan bilang ada seseorang di Colossus yang melanggar hukum Illumina.)",
  ui_story_30120401_6_dialog_content = "(Semoga ini bukan masalah besar...)",
  ui_story_30120401_7_dialog_content = "Kita sampai. Silakan duduk di mana pun.",
  ui_story_30120401_8_dialog_content = "Kursi ini... Sedikit keras.",
  ui_story_30120401_9_dialog_content = "Kau yang memilih perabot di sini, Nemesis? Ini...?",
  ui_story_30120401_10_dialog_content = "Terkejut? Semua perabot ini terbuat dari <color=#FFB400>logam</color>.",
  ui_story_30120401_11_dialog_content = "Ya, terutama kursi ini. Terlihat berat...",
  ui_story_30120401_12_dialog_content = "Itu dari besi tuang, begitu juga lemarinya. Daun jendela terbuat dari baja berlapis timah, dan cangkir-cangkir terbuat dari aluminium berlapis yang ringan.",
  ui_story_30120401_13_dialog_content = "Jadi, begitu... Cangkir ini juga terlihat berat...",
  ui_story_30120401_14_dialog_content = "Perlu waktu untuk membiasakan diri, selain itu, benda-benda ini juga bisa digunakan untuk melatih lengan.",
  ui_story_30120401_15_dialog_content = "Oh, jadi kamu suka berolahraga, Nemesis? Seingatku ada Exercise Center di Colossus...",
  ui_story_30120401_16_dialog_content = "Oh, hmm... Tidak juga, sih. Hanya saja menurutku barang-barang dari logam lebih tahan lama.",
  ui_story_30120401_17_dialog_content = "Lebih tahan lama? Hmm... Oh, aku paham sekarang, Nemesis!",
  ui_story_30120401_18_dialog_content = "Kau pasti punya hewan peliharaan atau semacamnya, 'kan? Kau tidak ingin peliharaanmu merusak apa pun dan itulah sebabnya...",
  ui_story_30120401_19_dialog_content = "Tidak, ini untukku.",
  ui_story_30120401_20_dialog_content = "Kamu?",
  ui_story_30120401_21_dialog_content = "Percaya atau tidak, tapi aku sering sekali merusak barang-barang.",
  ui_story_30120401_22_dialog_content = "Tapi kau tak terlihat seperti orang yang sangat temperamental, dan aku belum pernah melihat kamu melempar barang apa pun di Colossus. Kecuali...",
  ui_story_30120401_23_dialog_content = "Ini karena pekerjaan.",
  ui_story_30120401_24_dialog_content = "Pekerjaan? Kau kan' General Inspector, bukan tukang pipa...",
  ui_story_30120401_25_dialog_content = "Ini karena keadilan! Keadilan membakar hatiku bagaikan api, dan terkadang aku tak bisa membendungnya...",
  ui_story_30120401_26_dialog_content = "Sepertinya aku tidak paham...",
  ui_story_30120401_27_dialog_content = "Saat aku membaca berkas-berkas kasus dan melihat semua ketidakadilan itu, aku cenderung menghancurkan apa pun yang sedang kupegang di tanganku.",
  ui_story_30120401_28_dialog_content = "Saat aku tidak sedang membaca berkas-berkas kasus pun, hanya memikirkan ketidakadilan itu membuatku kesal lalu melakukan hal yang sama.",
  ui_story_30120401_29_dialog_content = "Aku tak pernah memperhatikan hal ini sebelumnya. Bahkan aku memecahkan 97 gelas dalam seminggu sebelum Chief Vivian menunjukkannya kepadaku.",
  ui_story_30120401_30_dialog_content = "Saat itulah aku memutuskan untuk mengganti semua perabotku dengan perabot <color=#FFB400>logam</color> karena cukup tahan lama.",
  ui_story_30120401_31_dialog_content = "Dengan begitu, tiap kali aku merasa kesal lantaran melihat atau memikirkan ketidakadilan itu, aku tidak akan merusak apa pun.",
  ui_story_30120401_32_dialog_content = "Aku paham. Aku tak pernah tahu ternyata kau adalah General Inspector yang sangat bersemangat...",
  ui_story_30120401_33_dialog_content = "Ini juga ada hubungannya dengan alasanku memintamu untuk datang hari ini.",
  ui_story_30120401_34_dialog_content = "Oh, iya. Kau belum memberitahuku. Ada apa?",
  ui_story_30120401_35_dialog_content = "Aku ingin kau mengirimkan sesuatu kepada Vice.",
  ui_story_30120401_36_dialog_content = "Hah... Coba aku tebak, barangnya terbuat dari <color=#FFB400>kaca</color>, bukan?",
  ui_story_30120401_37_dialog_content = "Ya!",
  ui_story_30120401_38_dialog_content = "Kurir!",
  ui_story_30120401_39_dialog_content = "Ini barang yang kau minta, General Inspector.",
  ui_story_30120401_40_dialog_content = "Bagus sekali, letakkan di atas meja.",
  ui_story_30120401_41_dialog_content = "Buka dan lihatlah, PlayerName.",
  ui_story_30120401_42_dialog_content = "Oh... Ini set peralatan makan?",
  ui_story_30120401_43_dialog_content = "Ya, satu <color=#FFB400>cangkir kopi porselen</color>, dua <color=#FFB400>piring</color>, dan satu <color=#FFB400>tutup gelas</color>.",
  ui_story_30120401_44_dialog_content = "Kau menyiapkan ini untuk Vice?",
  ui_story_30120401_45_dialog_content = "Beberapa hari yang lalu, Vice menerima <color=#FFB400>Field Service Award</color>. Inilah hadiahnya.",
  ui_story_30120401_46_dialog_content = "Field Service Award? Apa itu?",
  ui_story_30120401_47_dialog_content = "Eng... Jika aku harus menjawab, itu adalah penghargaan bagi mereka yang sering bekerja di lapangan. Itu adalah ide <color=#FFB400>Chief Vivian</color>, jadi aku tak begitu tahu secara spesifik.",
  ui_story_30120401_48_dialog_content = "Karena Chief Vivian sangat sibuk, dia memintaku untuk memberikan ini kepada tiga penerima penghargaan, dan Vice adalah salah satunya.",
  ui_story_30120401_49_dialog_content = "Tapi aku paling tak bisa mengurus benda-benda yang terbuat dari kaca...",
  ui_story_30120401_50_dialog_content = "Karena lebih baik jika seseorang menerima hadiah dari orang terdekatnya, aku jadi teringat padamu.",
  ui_story_30120401_51_dialog_content = "Oh, begitu, bukan masalah! Jadi, hanya Vice, 'kan?",
  ui_story_30120401_52_dialog_content = "Yah, ada Charon dan Philyshy juga, tapi aku sudah mempercayakan hadiah mereka kepada orang lain untuk dikirim.",
  ui_story_30120401_53_dialog_content = "Aku mengerti. Aku akan mengantarkan ini kepadanya sekarang juga.",
  ui_story_30120401_54_dialog_content = "Oh, tolong beri dia pesan ini saat kau mengirimkan hadiahnya:",
  ui_story_30120401_55_dialog_content = "\"Ini dari Chief Vivian, sebagai penghargaan atas tindakanmu pada <color=#FFB400>hari itu, satu bulan yang lalu</color>.\"",
  ui_story_30120401_56_dialog_content = "Itu saja?",
  ui_story_30120401_57_dialog_content = "Ya.",
  ui_story_30120401_58_dialog_content = "Itu terdengar... Agak kurang jelas.",
  ui_story_30120401_59_dialog_content = "Ya, tapi itulah yang direncanakan Chief Vivian, jadi turuti saja.",
  ui_story_30120401_60_dialog_content = "Baiklah kalau begitu, aku akan pergi.",
  ui_story_30120401_61_dialog_content = "Jangan lupa.",
  ui_story_30120401_62_dialog_content = "Tentu saja!",
  ui_story_30120401_63_dialog_content = "(Vice... Seharusnya dia masih ada di Colossus. Aku akan mencarinya.)",
  ui_story_30120401_64_dialog_content = "Ah! Kau di situ rupanya, Vice!",
  ui_story_30120401_65_dialog_content = "Hmm? Apa ini, PlayerName?",
  ui_story_30120401_66_dialog_content = "Field Service Award milikmu.",
  ui_story_30120401_67_dialog_content = "Field Service Award? Aneh, pasti ini penghargaan baru... Sejak kapan para petinggi mulai merasa begitu murah hati...",
  ui_story_30120401_68_dialog_content = "Ini ide Chief Vivian.",
  ui_story_30120401_69_dialog_content = "Chief of Staff itu?",
  ui_story_30120401_70_dialog_content = "Ya! Oh, ada pesan juga!",
  ui_story_30120401_71_dialog_content = "\"Ini dari Chief Vivian, sebagai penghargaan atas tindakanmu pada hari itu, satu bulan yang lalu.\"",
  ui_story_30120401_72_dialog_content = "Satu bulan yang lalu...",
  ui_story_30120401_73_dialog_content = "Ada masalah, Vice? Kau terlihat...",
  ui_story_30120401_74_dialog_content = "Kau tidak suka hadiahmu?",
  ui_story_30120401_75_dialog_content = "Eh... Bukan itu!",
  ui_story_30120401_76_dialog_content = "(Suaranya terdengar tegang dan senyumnya terlihat dipaksakan.)",
  ui_story_30120401_77_dialog_content = "(Apakah Vice pernah melihat set peralatan makan ini sebelumnya?)",
  ui_story_30120401_78_dialog_content = "Eng... Kamu baik-baik saja, Vice?",
  ui_story_30120401_79_dialog_content = "Hmm? Aku baik-baik saja. Aku hanya perlu istirahat. Ini hadiah yang indah. Sampai jumpa.",
  ui_story_30120401_80_dialog_content = "Hah? Vice?",
  ui_story_30120401_81_dialog_content = "(Aneh... Apakah itu berarti dia tidak menyukainya?)",
  ui_story_30120401_82_dialog_content = "(Atau apakah Vice memiliki kecenderungan aneh yang sama untuk memecahkan benda yang terbuat dari kaca?)",
  ui_story_30120401_83_dialog_content = "(Tidak mungkin... Sudahlah, kurasa aku akan pergi saja...)",
  ui_story_30120401_84_dialog_content = "<color=#e8d9bb>Keesokan harinya, di Bridge</color>",
  ui_story_30120401_85_dialog_content = "Di situ kau rupanya, Navigator.",
  ui_story_30120401_86_dialog_content = "Hei, Nemesis. Ada waktu luang untuk mengunjungi Bridge hari ini?",
  ui_story_30120401_87_dialog_content = "Kau sudah memberikan hadiah itu kepada Vice?",
  ui_story_30120401_88_dialog_content = "Ya, aku memberikan hadiah itu kepadanya kemarin. Ada masalah?",
  ui_story_30120401_89_dialog_content = "Apakah Vice mengatakan sesuatu setelahnya?",
  ui_story_30120401_90_dialog_content = "(Vice pasang ekspresi aneh di wajahnya saat melihat set peralatan makan itu kemarin...)",
  ui_story_30120401_91_dialog_content = "(Tapi haruskah aku memberitahunya?)",
  ui_story_30120401_92_option_content = "Jangan katakan semuanya.",
  ui_story_30120401_93_dialog_content = "(Aku tidak boleh berkata banyak padanya... Lagi pula, hal itu tampaknya cukup pribadi untuk Vice...)",
  ui_story_30120401_94_dialog_content = "Eh... T-tidak juga.",
  ui_story_30120401_95_dialog_content = "Benarkah? Navigator, kau tidak menyembunyikan informasi, 'kan?",
  ui_story_30120401_96_dialog_content = "(Sial, sepertinya aku tidak bisa menyembunyikannya.)",
  ui_story_30120401_97_dialog_content = "Dia memang General Inspector dari Illumina...",
  ui_story_30120401_98_option_content = "Sepertinya aku harus memberitahunya.",
  ui_story_30120401_99_dialog_content = "Eng, sebenarnya dia...",
  ui_story_30120401_100_dialog_content = "Sudah kuduga... Bisakah kau menceritakan selengkapnya?",
  ui_story_30120401_101_dialog_content = "Yah, dari raut wajahnya setelah dia menerima hadiah itu tampaknya ada sesuatu yang tidak beres.",
  ui_story_30120401_102_dialog_content = "Hmm... Kau melihat alasannya? Apakah karena hadiahnya?",
  ui_story_30120401_103_dialog_content = "Sepertinya bukan.",
  ui_story_30120401_104_dialog_content = "Lalu apa?",
  ui_story_30120401_105_dialog_content = "Aku... Aku pikir itu karena pesan untuknya yang kau titipkan padaku.",
  ui_story_30120401_106_dialog_content = "\"Ini dari Chief Vivian, sebagai penghargaan atas tindakanmu pada hari itu, satu bulan yang lalu.\"",
  ui_story_30120401_107_dialog_content = "Artinya, Vice...",
  ui_story_30120401_108_dialog_content = "Eh... Ada yang tidak beres?",
  ui_story_30120401_109_dialog_content = "Jadi, begitu, ya...",
  ui_story_30120401_110_dialog_content = "Eh... Ada yang tidak beres?",
  ui_story_30120401_111_dialog_content = "Tidak apa-apa. Yang penting hadiahnya sudah disampaikan. Sekarang, aku ada hal lain yang harus kuurus.",
  ui_story_30120401_112_dialog_content = "Ah, baiklah...",
  ui_story_30120401_113_dialog_content = "<color=#FFB400>Vice</color>... <color=#FFB400>Charon</color>... <color=#FFB400>Philyshy</color>...",
  ui_story_30120401_114_dialog_content = "Apakah Nemesis menyebut nama mereka? Lalu... Apa itu benar-benar hadiah?",
  ui_story_30120401_115_dialog_content = "Ketika Vice melihat hadiah itu, kenapa dia terlihat...",
  ui_story_30120401_116_dialog_content = "Hmm, ekspresinya terlihat berubah hanya saat aku menyebutkan tentang <color=#FFB400>satu bulan yang lalu</color>...",
  ui_story_30120401_117_dialog_content = "Apa yang terjadi pada hari itu?",
  ui_story_30120601_1_dialog_content = "Hei, nak.",
  ui_story_30120601_2_dialog_content = "Aku butuh bantuanmu untuk sesuatu.",
  ui_story_30120601_3_dialog_content = "Ada apa?",
  ui_story_30120601_4_dialog_content = "Anda akrab dengan semua orang di Colossus, bukan? Bisakah Anda memberi tahu saya jika Anda kebetulan melihat orang ini?",
  ui_story_30120601_5_dialog_content = "Lihat siapa? Apakah seseorang memberimu masalah?",
  ui_story_30120601_6_dialog_content = "Tapi yang pertama dan terpenting, tidak akan ada pertempuran di dalam Colossus!",
  ui_story_30120601_7_dialog_content = "Dia mungkin telah menyebabkan saya beberapa masalah tapi, sungguh, saya harus berterima kasih padanya!",
  ui_story_30120601_8_dialog_content = "Saya bosan hari itu, mungkin karena terlalu banyak kedamaian baru-baru ini.",
  ui_story_30120601_9_dialog_content = "Saya bahkan tidak mau repot-repot menghadiri pertemuan Legiun. Yang ingin saya lakukan hanyalah tinggal di dalam dan bermain game.",
  ui_story_30120601_10_dialog_content = "Tapi tiba-tiba petir menyambar!",
  ui_story_30120601_11_dialog_content = "Sesosok yang membawa mikrofon muncul di hadapanku, menyebut dirinya The Punisher.",
  ui_story_30120601_12_dialog_content = "♪ Hei, kemana kepalamu? Komandan tidak bisa hanya duduk-duduk bermain game ♪",
  ui_story_30120601_13_dialog_content = "♪ Mungkin tidak ada urgensi, tapi bersiaplah tetap menjadi kunci ♪",
  ui_story_30120601_14_dialog_content = "♪ Ini bukan hanya strategi, tetapi nyawa dan anggota tubuh orang! Dan, periksa, apakah kamu masih tidak bisa berenang ♪",
  ui_story_30120601_15_dialog_content = "Apa? Kenapa ekorku berasap?!",
  ui_story_30120601_16_dialog_content = "Pada saat saya mengeluarkan ekor api saya, sosok itu sudah hilang.",
  ui_story_30120601_17_dialog_content = "Ah, jadi itu sebabnya ekormu terlihat terbakar. Ini cukup hangus. Sayang sekali.",
  ui_story_30120601_18_dialog_content = "Harga kecil yang harus dibayar, sungguh, mengingat Punisher ini agak membangunkan saya dan menghentikan saya dari mendekam.",
  ui_story_30120601_19_dialog_content = "Itu sebabnya saya membutuhkan Anda untuk membantu saya menemukannya dan berterima kasih padanya secara pribadi.",
  ui_story_30120601_20_dialog_content = "Jadi seperti apa Punisher ini?",
  ui_story_30120601_21_dialog_content = "Aku, eh, begitu asyik dengan permainanku sehingga aku bahkan tidak menyadarinya.",
  ui_story_30120601_22_dialog_content = "Saya hanya melihat dia memegang petir, serta mikrofon mewah.",
  ui_story_30120601_23_dialog_content = "Itu tidak benar-benar membunyikan bel, tapi aku akan mengawasimu.",
  ui_story_30120601_24_dialog_content = "Terima kasih banyak!",
  ui_story_30120601_25_dialog_content = "Namun, aku harus pergi sekarang, untuk menasihati Grand Marshal agar menyerang Lumopolis! Astra harus bersatu!",
  ui_story_30120601_26_dialog_content = "Wow... Benar-benar bermusuhan...",
  ui_story_30120601_27_dialog_content = "Anda tahu, hal yang sama terjadi pada saya, meong!",
  ui_story_30120601_28_dialog_content = "Apakah Anda bertemu dengan Punisher juga?",
  ui_story_30120601_29_dialog_content = "Saya tidak tahu apakah itu orang yang sama, tetapi pada hari ...",
  ui_story_30120601_30_dialog_content = "Saya sedang bekerja, dan entah bagaimana tertidur, meong!",
  ui_story_30120601_31_dialog_content = "Saat itu, petir menyambar!",
  ui_story_30120601_32_dialog_content = "Kepalaku masih belum jernih, dan yang kulihat hanyalah sesosok samar yang memegang mikrofon.",
  ui_story_30120601_33_dialog_content = "♪ Harus dikatakan: Intel Chief tidur seperti wow, saat melihat orang lain selalu mengeong ♪",
  ui_story_30120601_34_dialog_content = "♪Dengan perut terbuka, dia sangat kawaii, tapi saat musuh datang, semuanya byeeee ♪",
  ui_story_30120601_35_dialog_content = "♪ Terserah, beri hadiah, sepotong keju saja. Tapi setidaknya itu gratis, Anda harus senang ♪",
  ui_story_30120601_36_dialog_content = "Aku bahkan tidak mendengar dengan jelas apa yang mereka gumamkan, tapi aku mencium bau terbakar...",
  ui_story_30120601_37_dialog_content = "Waaah! Ekorku berasap, meong!",
  ui_story_30120601_38_dialog_content = "Boo-hoo, aku pingsan di sana dan kemudian...",
  ui_story_30120601_39_dialog_content = "Saat aku bangun, orang itu sudah pergi.",
  ui_story_30120601_40_dialog_content = "Sepertinya pelakunya sama.",
  ui_story_30120601_41_dialog_content = "Dari mana asalmu, Vice?!",
  ui_story_30120601_42_dialog_content = "Saya telah beristirahat di sana selama ini. Saya hanya mendengarkan.",
  ui_story_30120601_43_dialog_content = "Apakah Anda kebetulan melihat orang itu dengan baik, Petugas Philyshy?",
  ui_story_30120601_44_dialog_content = "Tidak, meong! aku masih grogi...",
  ui_story_30120601_45_dialog_content = "Sepertinya aku ingat bahwa mereka tidak berseragam Illumina tapi sepertinya mengenakan rok panjang...",
  ui_story_30120601_46_dialog_content = "Cakar saya memang memiliki rambut pirang. Aku terus bertanya-tanya apakah aku memimpikan Yumi...",
  ui_story_30120601_47_dialog_content = "Ah, aku harus kembali bekerja sekarang. Tidak ada lagi tidur di tempat kerja untukku, meong!",
  ui_story_30120601_48_dialog_content = "Sepertinya Punisher suka menyetrum mereka yang berekor?",
  ui_story_30120601_49_dialog_content = "Kamu harus berhati-hati, Vice. Bagaimana jika Anda bertemu dengan orang ini juga...?",
  ui_story_30120601_50_dialog_content = "Jangan khawatirkan aku, oke? Bukankah saya selalu menganggap serius pekerjaan saya? Maksudku, aku bahkan menemukan harta karun sepertimu...",
  ui_story_30120601_51_dialog_content = "Aduh! Apa yang begitu panas?!",
  ui_story_30120601_52_dialog_content = "Dapatkan perhatian Anda sekarang, eh ?! Berikan sambutan hangat kepada Punisher!",
  ui_story_30120601_53_dialog_content = "Dia disini!",
  ui_story_30120601_54_dialog_content = "Hah? Darimana datangnya cahaya?! Mengapa ada lampu panggung di sini?",
  ui_story_30120601_55_dialog_content = "♪ Waktunya untuk béda Wakil, betcha tidak punya liburan lagi ♪",
  ui_story_30120601_56_dialog_content = "♪ Kapten tim eksplorasi. Temukan Caelestite, lalu tinggalkan yang lain kehilangan ♪",
  ui_story_30120601_57_dialog_content = "♪ Terlambat untuk rapat, biarkan Vivian disalahkan. Apakah Anda benar-benar di sini untuk bekerja, atau Anda hanya bermain-main ♪",
  ui_story_30120601_58_dialog_content = "Oh tidak! Maafkan aku, aku harus lari! Saya benar-benar lupa tentang pertemuan hari ini!",
  ui_story_30120601_59_dialog_content = "Keburukan! Ekormu!",
  ui_story_30120601_60_dialog_content = "Umm, uh... Tidak apa-apa! Saya baik-baik saja! Harus pergi!",
  ui_story_30120601_61_dialog_content = "Mata yang lain akhirnya terbuka. Sungguh memusingkan... Aku takut memikirkan apa yang akan terjadi tanpaku!",
  ui_story_30120601_62_dialog_content = "Namun, tidak ada istirahat bagi orang jahat. Masih banyak pekerja yang harus bangun.",
  ui_story_30120601_63_option_content = "Buka identitasnya",
  ui_story_30120601_64_dialog_content = "Tunggu sebentar... Aku tahu siapa kamu.",
  ui_story_30120601_65_dialog_content = "Orang lain mungkin tidak mengenali Anda dalam kostum baru Anda yang mewah, tetapi tidak ada yang bisa lolos dari penglihatan tajam Caelestite saya!",
  ui_story_30120601_66_option_content = "Ayo! Bawa itu padanya!",
  ui_story_30120601_67_dialog_content = "♪ Pikirkan benang baru Anda yang mewah dapat menarik perhatian kami ♪",
  ui_story_30120601_68_dialog_content = "♪ Skulk dalam bayang-bayang, tapi bodoh, aku seorang Caelestite—jangan bertingkah terlalu kaget ♪",
  ui_story_30120601_69_dialog_content = "♪ Anda mencoba yang terbaik untuk menjaga rahasia Anda dan melakukan tugas Anda, tapi lihat, Anda GAGAL, bodoh, dan saya melepas topeng Anda ♪",
  ui_story_30120601_70_dialog_content = "Anda Nemesis, AKA Penegak Keadilan!",
  ui_story_30120601_71_dialog_content = "Mengapa Anda melakukan semua ini untuk menipu orang?",
  ui_story_30120601_72_dialog_content = "Pff, Anda mungkin telah membuka kedok saya, tapi tetap saja ...",
  ui_story_30120601_73_dialog_content = "Giliranku!",
  ui_story_30120601_74_dialog_content = "♪ Diam, tidak ada yang peduli kamu Caelestite! Cobalah berbuat baik daripada duduk-duduk setiap malam ♪",
  ui_story_30120601_75_dialog_content = "♪ Mengepakkan gusimu seperti sedang belajar, tapi hanya mengandalkan genmu—aku yakin itu ♪",
  ui_story_30120601_76_dialog_content = "♪ Hanya peduli pada materi, itu adalah kelamin, dan tidak ada yang menghentikan serial ini ♪",
  ui_story_30120601_77_dialog_content = "♪ Hari ini saya membawa peringatan, dan Anda sebaiknya percaya skornya, saya tidak akan membiarkan Anda memelintir hati orang-orang lagi ♪",
  ui_story_30120601_78_dialog_content = "Kamu... Aku tidak seperti itu... Aku tidak....",
  ui_story_30120601_79_dialog_content = "Aduh...",
  ui_story_30120601_80_dialog_content = "Hey bangun! Apakah kamu baik-baik saja?",
  ui_story_30120601_81_dialog_content = "Hah...? Apa yang kamu lakukan di sini?",
  ui_story_30120601_82_dialog_content = "Saya datang ketika saya punya waktu luang, hanya untuk menemukan Anda kedinginan.",
  ui_story_30120601_83_dialog_content = "Aku tidak tahu apa yang baru saja terjadi, tapi tiba-tiba aku merasa sangat menyesal dan pingsan...",
  ui_story_30120601_84_dialog_content = "Sepertinya Anda juga membuat Punisher menghakimi Anda, meong.",
  ui_story_30120601_85_dialog_content = "Anda bertemu dengan Punisher juga? Apakah Anda melihatnya dengan baik?",
  ui_story_30120601_86_dialog_content = "Aku tahu siapa dia! Dia...",
  ui_story_30120601_87_dialog_content = "Nemesis!",
  ui_story_30120601_88_dialog_content = "Apa? Betulkah? Tapi Punisher tidak berseragam?",
  ui_story_30120601_89_dialog_content = "Ahaha! Saya pikir PlayerName pasti tertidur lelap seperti saya, meong!",
  ui_story_30120601_90_dialog_content = "Apakah anak ini sedang bermimpi? Yah, apapun. Aku punya sesuatu yang harus dilakukan, jadi sampai jumpa lagi.",
  ui_story_30120601_91_dialog_content = "Apakah Anda sudah berlebihan? Mengapa tidak kembali ke kamar Anda dan beristirahat dengan baik? Aku akan sibuk sekarang.",
  ui_story_30120601_92_dialog_content = "Hah? Mungkinkah aku benar-benar bermimpi barusan?",
  ui_story_30120601_93_dialog_content = "♪ Tidak bisa membedakan apa yang nyata dari apa yang tidak? Kepala Caelestite masih ada di langit ♪",
  ui_story_30120601_94_dialog_content = "♪ Lebih baik bangun ke kenyataan, ketika begitu banyak dari apa yang Anda katakan akan Anda lakukan, ternyata bohong ♪",
  ui_story_30120601_95_dialog_content = "Aku tahu aku tidak memimpikannya! Itu dia!",
